// D18 probe: the product's fast path, plus recall on user-prompt when SOFAR_PROBE_RECALL is set.
import { runFast as productRunFast, parseHookFlags } from '$E/cli/fast'
import { handleUserPrompt, mirror, readStdin } from '$E/cli/event'
import { createToolContext, resolveSessionFirst } from '$E/mcp/context'
import { recall, type Variant } from './recall'

export async function runFast(argv: readonly string[]): Promise<boolean> {
  const [command, name, ...flags] = argv.slice(2)
  const v = process.env.SOFAR_PROBE_RECALL
  if (command === 'event' && name === 'user-prompt' && v !== undefined && v !== 'off') {
    const parsed = parseHookFlags(flags)
    if (parsed === null) return false
    const input = await readStdin()
    const result = handleUserPrompt(parsed.root, input, parsed.host)
    try {
      const hook = JSON.parse(input) as { session_id?: string; prompt?: string }
      const ctx = createToolContext(parsed.root)
      const r = resolveSessionFirst(ctx, hook.session_id ?? null)
      if (r !== null) {
        const state = ctx.foldState(r.slug)
        const { block } = recall(ctx.sofarDir, state, r.slug, String(hook.prompt ?? ''), v as Variant)
        result.stdout += block
      }
    } catch {
      // probe: a failure leaves the product output as is
    }
    mirror(result)
    return true
  }
  return productRunFast(argv)
}
